sys_ui_action.script:
// bfd_ui_escalate_case — raise the escalation level, make the SLA position
// explicit, and let the existing escalation notification fire on the change.
(function escalateCaseAction() {
    var engine = new bfd_TriageEngine();

    var level = parseInt(current.getValue('escalation_level') || '0', 10);
    if (isNaN(level) || level < 0) level = 0;
    var next = level + 1;
    current.setValue('escalation_level', next);

    var slaNote = '';
    var expected = current.getValue('expected_resolution_date');
    var breached = current.getValue('sla_breach_flag') === 'true' || current.getValue('sla_breach_flag') === '1';
    if (!breached && expected) {
        var due = new GlideDateTime(expected);
        if (due.getNumericValue() < new GlideDateTime().getNumericValue()) {
            current.setValue('sla_breach_flag', true);
            breached = true;
            slaNote = ' The expected resolution date has passed, so the SLA breach flag has been set.';
        }
    } else if (breached) {
        slaNote = ' This case is already flagged as an SLA breach.';
    }

    engine.logAiDecision(current, {
        note:
            'Case escalated by ' +
            gs.getUserDisplayName() +
            ' from escalation level ' +
            level +
            ' to ' +
            next +
            '.' +
            slaNote,
        finalDecision: 'escalation_level=' + next,
    });
    current.update();

    gs.addInfoMessage(
        'Case escalated to level ' +
            next +
            '. The escalation notification will be sent to the team lead and the change is recorded in the audit trail.' +
            slaNote
    );
    action.setRedirectURL(current);
})();
